mapper.select:
select id, type, user_id, start_time, end_time, day
from duration
where user_id = #{userId}
and `type` = #{type}
order by id desc
limit 1

select day,
       `type`,
       count(1) as sessionCount
from duration
where user_id = #{userId}
  and day between #{startDay} and #{endDay}
  and `type` in

      #{type}

group by day, `type`
order by day asc
